-- Valid/dirty state for 4 cache lines. Each request is one operation on
-- one line: read (miss fills the line), write (sets dirty), evict
-- (writes back a dirty line, then invalidates it). Only one op rule can
-- fire per cycle, but three of them write `valid`, so they are chained.
xblue module mkLineState;
  input Bool reset;
  input Bool req_valid;
  input Bit#(2) req_op;     -- 0 read, 1 write, 2 evict
  input Bit#(2) req_line;

  Reg#(Vector#(4, Bool)) valid <- mkReg(0);
  Reg#(Vector#(4, Bool)) dirty <- mkReg(0);
  Reg#(Bit#(8)) misses <- mkReg(0);
  Reg#(Bit#(8)) writebacks <- mkReg(0);

  Bool hit   = valid[req_line];
  Bool isRd  = req_valid && req_op == 0;
  Bool isWr  = req_valid && req_op == 1;
  Bool isEv  = req_valid && req_op == 2;

  method Bool io_hit       = req_valid && hit;
  method Bool io_writeback = isEv && hit && dirty[req_line];
  method Bit#(4) io_valid  = valid;
  method Bit#(4) io_dirty  = dirty;

  rule readMiss (isRd && !hit);
    valid[req_line] <= True;
    misses <= misses + 1;
  endrule

  rule write (isWr);
    valid[req_line] <= True;
    dirty[req_line] <= True;
  endrule

  rule evict (isEv && hit);
    valid[req_line] <= False;
    dirty[req_line] <= False;
  endrule

  rule countWb (isEv && hit && dirty[req_line]);
    writebacks <= writebacks + 1;
  endrule

  rule clear (reset);
    valid <= 0;
    dirty <= 0;
  endrule

  -- the three op rules all write `valid`: they must be chained, not ∥
  schedule readMiss ≫ write ≫ evict ≫ countWb ≫ clear;
endmodule

-- ---------------------------------------------------------------- reasoning
open XBlue

structure Regs where
  valid : BitVec 4
  dirty : BitVec 4
  misses : BitVec 8
  writebacks : BitVec 8

/-- The registers after one clock cycle of the design itself. -/
def next (reset reqValid : BitVec 1) (op line : BitVec 2) (s : Regs) : Regs :=
  let r := (mkLineState.design.cycle (.cons reset (.cons reqValid (.cons op (.cons line .nil))))
              (.cons s.valid (.cons s.dirty (.cons s.misses (.cons s.writebacks .nil))))).regs
  ⟨r.get mkLineState.valid, r.get mkLineState.dirty, r.get mkLineState.misses, r.get mkLineState.writebacks⟩

/-- The line as a one-hot mask over the four valid / dirty bits. -/
def mask (line : BitVec 2) : BitVec 4 :=
  if line = 0#2 then 1#4 else if line = 1#2 then 2#4 else if line = 2#2 then 4#4 else 8#4

/-- The cycle as a story, in schedule order, one rule at a time. Each rule
    sees what the rules before it wrote. -/
def spec (reset reqValid : BitVec 1) (op line : BitVec 2) (s : Regs) : Regs :=
  let bit := mask line
  let isRd := reqValid = 1#1 ∧ op = 0#2
  let isWr := reqValid = 1#1 ∧ op = 1#2
  let isEv := reqValid = 1#1 ∧ op = 2#2
  -- readMiss: a missing line becomes valid
  let rm     := isRd ∧ s.valid &&& bit = 0#4
  let valid1 := if rm then s.valid ||| bit else s.valid
  let misses := if rm then s.misses + 1#8 else s.misses
  -- write: the line becomes valid and dirty
  let valid2 := if isWr then valid1 ||| bit else valid1
  let dirty2 := if isWr then s.dirty ||| bit else s.dirty
  -- evict: a valid line becomes invalid and clean
  let ev     := isEv ∧ valid2 &&& bit ≠ 0#4
  let valid3 := if ev then valid2 &&& ~~~bit else valid2
  let dirty3 := if ev then dirty2 &&& ~~~bit else dirty2
  -- countWb: reads valid and dirty as evict left them
  let cw := isEv ∧ valid3 &&& bit ≠ 0#4 ∧ dirty3 &&& bit ≠ 0#4
  let wb := if cw then s.writebacks + 1#8 else s.writebacks
  -- clear
  ⟨if reset = 1#1 then 0#4 else valid3, if reset = 1#1 then 0#4 else dirty3, misses, wb⟩

theorem next_eq_spec (reset reqValid : BitVec 1) (op line : BitVec 2) (s : Regs) :
    next reset reqValid op line s = spec reset reqValid op line s := by
  obtain ⟨v, d, m, w⟩ := s
  simp [next, spec, mask, mkLineState.design, Design.cycle, mkLineState.schedule, mkLineState.interfaces,
    mkLineState.rules.readMiss, mkLineState.rules.write, mkLineState.rules.evict,
    mkLineState.rules.countWb, mkLineState.rules.clear, mkLineState.values.hit,
    mkLineState.values.isRd, mkLineState.values.isWr, mkLineState.values.isEv, mkLineState.signature,
    Sched.run, Action.step, Action.fires, writesIf, State.write, State.cur, State.read, HList.set,
    HList.get, Expr.eval, Expr.binVal, Expr.cmpVal, Common.putR, Common.putW, Common.memAt,
    mkLineState.valid, mkLineState.dirty, mkLineState.misses, mkLineState.writebacks,
    mkLineState.reset, mkLineState.req_valid, mkLineState.req_op, mkLineState.req_line, sliceWidth]
  bv_decide

/-- Consequences, each read off the story. -/
theorem writebacks_stuck (reset reqValid : BitVec 1) (op line : BitVec 2) (s : Regs) :
    (next reset reqValid op line s).writebacks = s.writebacks := by
  rw [next_eq_spec]; simp only [spec]; bv_decide

/-- A line is dirty only if it is valid, and every cycle keeps it so. -/
def Inv (s : Regs) : Prop := s.dirty &&& ~~~s.valid = 0#4

theorem inv_preserved (reset reqValid : BitVec 1) (op line : BitVec 2) (s : Regs)
    (h : Inv s) : Inv (next reset reqValid op line s) := by
  rw [next_eq_spec]; simp only [spec, Inv] at *; bv_decide

/-- A read miss is counted. -/
theorem read_miss_counted (line : BitVec 2) (s : Regs) (h : s.valid &&& mask line = 0#4) :
    (next 0#1 1#1 0#2 line s).misses = s.misses + 1#8 := by
  rw [next_eq_spec]; simp only [spec]; bv_decide

theorem evict_invalidates (op line : BitVec 2) (s : Regs) (h : op = 2#2) :
    (next 0#1 1#1 op line s).valid &&& mask line = 0#4 := by
  rw [next_eq_spec]; simp only [spec]; subst h; bv_decide

